-- ============================================================
--  014_denominaciones_cno_2026_y_estado
--
--  Completa las denominaciones CNO con el catálogo más reciente,
--  "CNO_2026_Actualizado.xlsx", hoja «Denominaciones - C.N.O.», y carga el
--  estado activa/inactiva que nunca se había cargado.
--
--  Por qué: tras la 009 (catálogo 2024) quedaban 385 denominaciones con el
--  código como descripción. Al cruzarlas con el catálogo 2026 resultó que 350
--  de ellas son exactamente las que ese catálogo marca como INACTIVAS
--  (`activa = 0`): el export 2024 las había omitido por eso. Ejemplo:
--  D-3121.009 "Citotecnólogo" figura bajo Optómetras y está dada de baja.
--  En base todas las filas tenían `estado = true` porque el flag no se cargó.
--
--  Qué hace:
--    1. Descripción: para toda fila cuya descripción siga siendo su código y
--       el catálogo 2026 traiga nombre. Cubre las 350 y cualquier otra.
--    2. Estado: refleja `activa` del catálogo 2026 en `estado`, en todas las
--       filas ORIGINALES que aparezcan en él. Las copias de análisis no se
--       tocan aquí: heredan al crearse y las existentes se tratan abajo.
--    3. Copias existentes: heredan descripción y estado de su denominación
--       original, igual que en la 010 (la descripción de la copia es la
--       clave del original).
--
--  Idempotente. NO lleva BEGIN/COMMIT: el runner envuelve cada archivo en su
--  transacción.
-- ============================================================

CREATE TEMP TABLE tmp_den_2026 (cod text PRIMARY KEY, descripcion text NOT NULL, activa smallint NOT NULL) ON COMMIT DROP;

