-- 1. Descripción real donde aún está el código
UPDATE clasificacion.cno_denominacion d
SET    desc_denominacion = t.descripcion
FROM   tmp_den_2026 t
WHERE  t.cod = d.cod_denominacion_cno
  AND  d.desc_denominacion = d.cod_denominacion_cno;

-- 2. Estado real del catálogo, solo en filas originales
UPDATE clasificacion.cno_denominacion d
SET    estado = t.activa
FROM   tmp_den_2026 t
WHERE  t.cod = d.cod_denominacion_cno
  AND  d.cno_cod_ocupacion !~ '-'
  AND  d.estado IS DISTINCT FROM t.activa;

-- 3. Copias existentes: heredan descripción y estado del original
UPDATE clasificacion.cno_denominacion copia
SET    desc_denominacion = original.desc_denominacion,
       estado            = original.estado
FROM   clasificacion.cno_denominacion original
WHERE  copia.desc_denominacion = original.cod_denominacion_cno
  AND  original.desc_denominacion <> original.cod_denominacion_cno
  AND  copia.cod_denominacion_cno <> original.cod_denominacion_cno;
